-- 商城自配送模块菜单权限修复（Boot 模式）
-- 用法：mysql -u root -p aryn_boot < 25delivery_menu_fix.sql
-- 作用：插入配送模块菜单/按钮权限，并分配给超级管理员(role_id='1')和默认租户

USE `aryn_boot`;

-- 1. 插入菜单和按钮权限（幂等：先删后插）
DELETE FROM `sys_menu` WHERE `id` LIKE '2100000000000000%';

-- 2. 分配给超级管理员角色（role_id='1', tenant_id='1590229800633634816')
DELETE FROM `sys_role_menu` WHERE `id` LIKE '2101000000000000%';

-- 3. 分配给默认租户（tenant_id='1590229800633634816'）
DELETE FROM `sys_tenant_menu` WHERE `id` LIKE '2102000000000000%';
